///
/// While `+0x21E` is set, `+0x20C` is incremented. After ten ticks it wraps to
/// zero and scans the four state slots at `+0x388 + i*4` of the object
/// referenced by `r13 - 0x5704`, looking for the value `3`. The resulting
/// index is passed to `0x80015200` and stored back at `+0x210`.
///
/// # Original
/// - Ghidra: `FUN_800154e0` at `0x800154E0` (156 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800154e0_FUN_800154e0.c`
///
/// # Arguments
/// - `this`: `pointGet` scene.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Increments/wraps `+0x20C`, calls the digit record refresher, and stores the
/// selected index at `+0x210`.
///
/// # Safety
/// `this` must be writable through `+0x21E`; the SDA pointer at
/// `r13 - 0x5704` must be readable.
///
/// # Confidence
/// high - the counter, scan and call order are all literal.
pub unsafe fn fn_800154e0(this: usize) {
    if platform::read_u8(this + 0x21E) == 0 {
        return;
    }

    let mut tick = platform::read_i32(this + 0x20C) + 1;
    platform::write_i32(this + 0x20C, tick);
    if tick <= 9 {
        return;
    }

    platform::write_i32(this + 0x20C, 0);
    let mut index = platform::read_i32(this + 0x210);
    let base = platform::read_u32(SDA_BASE - 0x5704) as usize;
    let mut slot = base + index as usize * 4;

    loop {
        index += 1;
        if index > 3 {
            index = 0;
            break;
        }
        let state = slot + 0x388;
        slot += 4;
        if platform::read_i32(state) == 3 {
            break;
        }
    }

    platform::call2(FN_80015200, p32(this), index as u32);
    platform::write_i32(this + 0x210, index);
}

/// Flashes the coin-pop-up counter colour.
///
/// Two eight-byte colour pairs at `r13 - 0x5A70` and `r13 - 0x5A60` are
/// initialised once. The byte at `+0x221` selects the pair and is cleared;
/// the selected words are then passed to virtual slot `+0x28` of the object
/// at `+0x1E0` with selectors `0` and `2`.
///
/// # Original
/// - Ghidra: `FUN_80015580` at `0x80015580` (304 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80015580_FUN_80015580.c`
///
/// # Arguments
/// - `this`: `pointGet` scene.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Initialises two SDA colour pairs, clears the one-shot byte `+0x221`, and
/// makes two virtual colour-setter calls.
///
/// # Safety
/// `this + 0x1E0` must hold a readable object pointer with a vtable at `+0`.
///
/// # Confidence
/// high - the guards, table selection and call shapes are literal.
pub unsafe fn fn_80015580(this: usize) {
    if platform::read_u8(SDA_BASE - 0x5A71) == 0 {
        for (offset, value) in [0xFFu8, 0x0A, 0x0A, 0xFF, 0x3C, 0x78, 0xFF, 0xFF]
            .iter()
            .enumerate()
        {
            platform::write_u8(SDA_BASE - 0x5A70 + offset, *value);
        }
        platform::write_u8(SDA_BASE - 0x5A71, 1);
    }

    if platform::read_u8(SDA_BASE - 0x5A68) == 0 {
        for (offset, value) in [0xFFu8, 0x96, 0x96, 0xFF, 0xC8, 0xF0, 0xFF, 0xFF]
            .iter()
            .enumerate()
        {
            platform::write_u8(SDA_BASE - 0x5A60 + offset, *value);
        }
        platform::write_u8(SDA_BASE - 0x5A68, 1);
    }

    let selected = platform::read_u8(this + 0x221) != 0;
    if selected {
        platform::write_u8(this + 0x221, 0);
    }
    let offset = if selected { 4usize } else { 0 };

    let owner = platform::read_u32(this + 0x1E0) as usize;
    let setter = vtable_method(owner, 0, 0x28);

    let mut first = crate::platform::GuestLocal::new( [0u32; 1]);
    first[0] = platform::read_u32(SDA_BASE - 0x5A70 + offset);
    platform::call3(setter, p32(owner), 0, first.as_ptr() as u32);

    let mut second = crate::platform::GuestLocal::new( [0u32; 1]);
    second[0] = platform::read_u32(SDA_BASE - 0x5A60 + offset);
    platform::call3(setter, p32(owner), 2, second.as_ptr() as u32);
}

/// Opens the battery warning window at a position and mode.
///
/// The window pane at `+0x1D4` is hidden first. When the debug/flag word at
/// `r13 - 0x5700` has bit `0x40` set and `mode < 8`, the function returns
/// without opening. Otherwise it copies the two-word position, stores the
/// mode and value, clears the interpolation words to the SDA2 zero float, and
/// resets the per-frame state.
///
/// # Original
/// - Ghidra: `FUN_80015ce0` at `0x80015CE0` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80015ce0_FUN_80015ce0.c`
///
/// # Arguments
/// - `this`: `batteryInfo` scene.
/// - `position`: pointer to two words (x/y) copied into `+0x19C`/`+0x1A0`.
/// - `mode`: stored at `+0x1FC`; also gates the debug early-out.
/// - `value`: stored at `+0x208`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Hides the pane, writes eight scene words and one byte, and clears the
/// state word at `+0x1F8`.
///
/// # Safety
/// `this` must be writable and `position` must point at two readable words.
///
/// # Confidence
/// high - every load and store is observed; the flag bit is unnamed.
pub unsafe fn fn_80015ce0(this: usize, position: usize, mode: i32, value: u32) {
    let pane = platform::read_u32(this + 0x1D4) as usize;
    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);

    if (platform::read_u32(SDA_BASE - 0x5700) & 0x40) != 0 && mode < 8 {
        return;
    }

    let zero = platform::read_u32(F32_SDA2_ZERO);
    let x = platform::read_u32(position);
    let y = platform::read_u32(position + 4);

    platform::write_i32(this + 0x1FC, mode);
    platform::write_u32(this + 0x208, value);
    platform::write_u32(this + 0x19C, x);
    platform::write_u32(this + 0x1A0, y);
    platform::write_u32(this + 0x1A4, zero);
    platform::write_u32(this + 0x1A8, zero);
    platform::write_u32(this + 0x1B4, zero);
    platform::write_u32(this + 0x1B8, zero);
    platform::write_u8(this + 0x21C, 0);
    platform::write_u32(this + 0x1F8, 0);
}

