/// Plays the error-window open animation for the selected button.
///
/// A 40-byte argument block is built with `0x800CDDB0`, then two keyframed
/// animations are started on the panes at `+0x1E0`/`+0x1E4`. The selected
/// button at `+0x220` indexes the two tables `0x802EDF48` and `0x802EDF64`.
/// The layout at `+8` is advanced, its animation is reset to frame `0x10`,
/// the pane at `+0x208` is hidden, and the open/advance byte `+0x22E` is
/// cleared.
///
/// # Original
/// - Ghidra: `FUN_800174c0` at `0x800174C0` (256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800174c0_FUN_800174c0.c`
///
/// # Arguments
/// - `this`: `errorInfo` scene.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Starts two animations, advances the layout to frame `0x10`, hides one
/// pane, and clears `+0x22E`.
///
/// # Safety
/// `this` must hold valid layout, animation and pane pointers.
///
/// # Confidence
/// medium - the call order and offsets are exact; the two tables' contents
/// are data and are not interpreted.
pub unsafe fn fn_800174c0(this: usize) {
    let mut scratch = crate::platform::GuestLocal::new( [0u8; 40]);
    let time = call0_r(FN_800CDC60);
    platform::call5(FN_800CDDB0, 1, scratch.as_mut_ptr() as u32, 0x10, 1, 0);

    let anim = platform::read_u32(this + 0x1E0);
    let index = platform::read_i32(this + 0x220) as usize * 4;
    platform::call6(
        FN_800C9A60,
        anim,
        time,
        platform::read_u32(DAT_802EDF48 + index),
        platform::read_u32(DAT_802EDF64 + index),
        1,
        scratch.as_ptr() as u32,
    );

    let anim2 = platform::read_u32(this + 0x1E4);
    let index2 = platform::read_i32(this + 0x220) as usize * 4;
    platform::call6(
        FN_800C9A60,
        anim2,
        time,
        platform::read_u32(DAT_802EDF48 + index2),
        platform::read_u32(DAT_802EDF64 + index2),
        1,
        scratch.as_ptr() as u32,
    );

    platform::call1(FN_800C9500, p32(this + 8));
    platform::call3(FN_800C93D0, p32(this + 8), 0x10, 0);
    platform::call3(FN_800C92F0, p32(this + 8), 0, 0);

    let pane = platform::read_u32(this + 0x208) as usize;
    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
    platform::write_u8(this + 0x22E, 0);
}

