/// Advances the coin-pop-up position and flashes its two offsets.
///
/// The pane selected by `+0x218` receives the base position `+0x1BC/+0x1C0`
/// plus the animated offsets `+0x1CC/+0x1D0` at `+0x44/+0x48`. A ten-tick
/// counter at `+0x214` toggles the direction byte at `+0x220`, and both offsets
/// then move by the `r2 - 0x7EC0` step (add when the byte is clear, subtract
/// when it is set).
///
/// # Original
/// - Ghidra: `FUN_80015780` at `0x80015780` (216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80015780_FUN_80015780.c`
///
/// # Arguments
/// - `this`: `pointGet` scene.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes two floats into the selected pane and four floats/one word into the
/// scene (`+0x214`, `+0x220`, `+0x1CC`, `+0x1D0`).
///
/// # Safety
/// `this + 0x1D8 + index*4` must hold a live pane pointer.
///
/// # Confidence
/// high - every load, arithmetic operation and store is literal.
pub unsafe fn fn_80015780(this: usize) {
    let step = platform::read_f32(F32_SDA2_POSITION_STEP);
    let base_x = platform::read_f32(this + 0x1BC);
    let base_y = platform::read_f32(this + 0x1C0);
    let offset_x = platform::read_f32(this + 0x1CC);
    let offset_y = platform::read_f32(this + 0x1D0);
    let index = platform::read_i32(this + 0x218) as usize;
    let pane = platform::read_u32(this + 0x1D8 + index * 4) as usize;

    platform::write_f32(pane + 0x44, base_x + offset_x);
    platform::write_f32(pane + 0x48, base_y + offset_y);

    let mut tick = platform::read_i32(this + 0x214) + 1;
    platform::write_i32(this + 0x214, tick);
    if tick > 9 {
        platform::write_i32(this + 0x214, 0);
        let next = if platform::read_u8(this + 0x220) == 0 { 1 } else { 0 };
        platform::write_u8(this + 0x220, next);
    }

    let mut new_x = platform::read_f32(this + 0x1CC);
    let mut new_y = platform::read_f32(this + 0x1D0);
    if platform::read_u8(this + 0x220) == 0 {
        new_x += step;
        new_y += step;
    } else {
        new_x -= step;
        new_y -= step;
    }
    platform::write_f32(this + 0x1CC, new_x);
    platform::write_f32(this + 0x1D0, new_y);
}

