    platform::call3(load, p32(this + 4), p32(S_YOKO_LAYOUT), 0);
    platform::call3(FN_800C8FB0, p32(this + 4), p32(TABLE_YOKO_ANIMS), 3);
    platform::call4(
        FN_800C90F0,
        p32(this + 4),
        p32(TABLE_YOKO_PANES),
        p32(DATA_YOKO_WINDOW),
        3,
    );

    let animation = platform::call1(FN_80007220, p32(this + 4));
    platform::write_u32(this + 0x1D8, animation);

    let player = platform::call2(THUNK_80007320, p32(this + 4), p32(S_YOKO_T_PLAYER));
    platform::write_u32(this + 0x1DC, player);

