/// - Ghidra: `FUN_80010dd0` at `0x80010DD0` (356 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80010dd0_FUN_80010dd0.c`
/// - Removed: the modelled `0x802DCD64`/`0x802DCDB0` calls. They are the
///   `_savegpr_23`/`_restgpr_23` compiler helpers (register spill/restore
///   only); the manager object is the incoming `r3`.
///
/// # Arguments
/// - `param_1`: manager object (`r3`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Visibility and alpha stores on six panes per iteration.
///
/// # Safety
/// The pane pointers read from `+0x3D4/+0x3E0` must be live.
///
/// # Confidence
/// medium - the loop and stores are literal; the per-player state table at
/// `SDA_BASE - 0x5704 + 0x28` and the query semantics are inferred.
pub unsafe fn fn_80010dd0(param_1: usize) {
    let root = param_1;
    let handle = platform::call2(FN_800E0380, platform::read_u32(G_SDA_5640), 0xFFFF_FFFF);
    let global = platform::read_u32(G_SDA_5704) as usize;

    let mut index = 0u32;
    let mut state_cursor = global + 8;
    let mut slot_cursor = root;
    loop {
        let outer = platform::read_u32(slot_cursor + 0x3E0) as usize;
        platform::write_u8(outer + 0xBB, platform::read_u8(outer + 0xBB) & 0xFE | 1);
        platform::write_u8(outer + 0xB8, 0xFF);
        let inner = platform::read_u32(slot_cursor + 0x3D4) as usize;
        platform::write_u8(inner + 0xB8, 0xFF);

        let mut keep_outer = false;
        if platform::read_i32(root + 0x40C) >= 0 {
            let valid = platform::call3(
                FN_80102750,
                platform::read_u32(root + 0x408),
                platform::read_u32(root + 0x40C),
                2,
            );
            if valid != 0 {
                keep_outer = true;
                let selected = platform::call4(
                    FN_800CE210,
                    handle,
                    platform::read_u32(root + 0x408),
                    platform::read_u32(root + 0x40C),
                    index,
                );
                let pane = platform::read_u32(slot_cursor + 0x3D4) as usize;
                if selected as u8 == 0 {
                    let same_player = platform::read_u32(root + 0x408)
                        == platform::read_u8(global + 0x20) as u32
                        && platform::read_u32(root + 0x40C)
                            == platform::read_u8(global + 0x21) as u32;
                    if same_player && platform::read_i32(state_cursor + 0x20) != 4 {
                        platform::write_u8(outer + 0xB8, 0);
                        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
                        platform::write_u8(pane + 0xB8, 0x46);
                    } else {
                        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
                    }
                } else {
                    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
                }
            }
        }

        if !keep_outer {
            platform::write_u8(outer + 0xBB, platform::read_u8(outer + 0xBB) & 0xFE);
        }

        index += 1;
        state_cursor += 4;
        slot_cursor += 4;
        if index > 2 {
            return;
        }
    }
}

