/// literal in the raw words and the export.
pub unsafe fn fn_80020ed0(this: usize, child: usize, mode: u8) {
    platform::write_u8(this + 0x680, 3);

    let digit_slot = vtable_method(child, 0x60, 0x6C);
    let digit = platform::read_u8(platform::call1(digit_slot, p32(child)) as usize);
    if digit != 0xFF {
        platform::write_u8(this + 0x670 + digit as usize, digit);
        platform::write_u8(this + 0x674, digit);
    }

    platform::write_u8(this + 0x68D, mode);
}

/// Consumes a state-`3` child when the owner test accepts it.
