const W203_FN_80088270: usize = 0x8008_8270;

/// `0x80060AB0` - per-player predicate over the table at `0x80354E20`.
const W203_FN_80060AB0: usize = 0x8006_0AB0;

/// `0x80066570(input)` - query on the input/rumble word.
