    let y = platform::read_f32(TABLE_DOKAN_DIRECTION + pair_index * 8 + 4);
    write_f32(this + 0xE8, sign * x);
    write_f32(this + 0xEC, sign * y);
    write_f32(this + 0xF0, platform::read_f32(F32_SDA2_7CD0));
