    effect_position[2] = platform::read_f32(F32_SDA2_7CA0_A);
    platform::call5(
        FN_8016C890,
        p32(S_WM_EN_OBAKEDOOR_A),
        0,
        p32(core::ptr::addr_of_mut!(effect_position) as usize),
        0,
        0,
    );

    let mut emitter_position = [0f32; 3];
    platform::call2(
        FN_8006CED0,
        p32(core::ptr::addr_of_mut!(emitter_position) as usize),
        p32(this),
    );
    platform::call5(
        FN_80066630_A,
        platform::read_u32(G_SDA_5940_A),
        p32(core::ptr::addr_of_mut!(emitter_position) as usize),
        0,
        1,
        0,
    );
