/// observed: the same four-character-spaced `"dokan_attack\0\0\0\0dead_leaf"`
/// run as the wave-204 table, but a distinct copy at a different address.
const S_DOKAN_ATTACK_B: usize = 0x8030_3A80;

/// `SDA2_BASE - 0x7C98` (`0x8042B3E8`): `1.0`, the scale applied to the
/// `+0x584` record by [`fn_8002be60`].
const F32_SDA2_7C98_B: usize = SDA2_BASE - 0x7C98;

/// `SDA2_BASE - 0x7C94` (`0x8042B3EC`): `0.0`, the alpha applied to the
/// `+0x584` record by [`fn_8002be60`].
const F32_SDA2_7C94_B: usize = SDA2_BASE - 0x7C94;

/// Per-frame tick of the leaf/door state machine: reset, update, notify.
///
/// The body is three literal steps:
/// 1. virtual slot `+0x1C` on the record at `+0x544`, with the record address
///    as its only argument (a per-frame reset/advance);
/// 2. virtual slot `+0x2AC` on the owner at `+0x60`, with `this`;
/// 3. when `0x80169020(this + 0x584)` answers non-zero (the animation-player
///    "finished" test), virtual slot `+0x2A8` on the owner with `this`, then
///    virtual slot `+0xD4` with `this` and the BSS record `0x80353090`.
///
/// # Original
/// - Ghidra: `FUN_8002b690` at `0x8002B690` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8002b690_FUN_8002b690.c`
///
/// # Arguments
/// - `this`: the actor; owner vtable at `+0x60`, record at `+0x544`,
///   animation at `+0x584`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two or four indirect calls; the notification pair only runs after the
/// `+0x584` animation has finished.
///
/// # Safety
/// `this` must be a live actor; `*(this + 0x60)` and `*(this + 0x544)` must be
/// readable vtables, and `this + 0x584` must be a live animation record.
///
/// # Confidence
/// high - the three vtable slots (`0x1C`, `0x2AC`, `0x2A8`, `0xD4`), the
/// `cmpi`-against-zero test and the `0x80353090` operand are literal.
pub unsafe fn fn_8002b690(this: usize) {
    // Virtual +0x1C on the +0x544 record, with the record as argument.
    let reset = vtable_method(this, 0x544, 0x1C);
    platform::call1(reset, p32(this + 0x544));

    // Virtual +0x2AC on the owner at +0x60.
    let update = vtable_method(this, 0x60, 0x2AC);
    platform::call1(update, p32(this));

    // 0x80169020(this + 0x584) != 0: the animation has finished.
    if platform::call1(FN_80169020, p32(this + 0x584)) != 0 {
        // Virtual +0x2A8 on the owner at +0x60.
        let finish = vtable_method(this, 0x60, 0x2A8);
        platform::call1(finish, p32(this));

        // Virtual +0xD4 on the owner at +0x60 with the state record.
        let notify = vtable_method(this, 0x60, 0xD4);
        platform::call2(notify, p32(this), p32(DAT_80353090_B));
    }
}

/// Per-frame tick without the animation-finished arm.
///
/// Same two leading steps as [`fn_8002b690`] (virtual `+0x1C` on the `+0x544`
/// record, then virtual `+0x298` on the owner at `+0x60`), but the notification
/// is gated by the state pair instead of the animation test: it fires only when
/// `+0x5D4` is non-zero **and** `+0x5CC` is `1` or `2`. The second test is
/// `addi r0,r3,-1` / `cmpli cr0,0,r0,0x1`, i.e. an unsigned `x - 1 < 2`, so
/// `0` and values above `2` both skip the notify.
///
/// # Original
/// - Ghidra: `FUN_8002b780` at `0x8002B780` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8002b780_FUN_8002b780.c`
///
/// # Arguments
/// - `this`: the actor; owner vtable at `+0x60`, record at `+0x544`, state at
///   `+0x5CC`/`+0x5D4`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two indirect calls, plus the `+0xD4` notification with the BSS record
/// `0x80353010` when the state pair matches.
///
/// # Safety
/// `this` must be a live actor and both vtables readable; `+0x5CC`/`+0x5D4`
/// must be readable words.
///
/// # Confidence
/// high - both guards and the `0x80353010` operand are literal, and the
/// unsigned `-1`/`cmpli 1` ladder is explicit in the disassembly.
pub unsafe fn fn_8002b780(this: usize) {
    // Virtual +0x1C on the +0x544 record.
    let reset = vtable_method(this, 0x544, 0x1C);
    platform::call1(reset, p32(this + 0x544));

    // Virtual +0x298 on the owner at +0x60.
    let update = vtable_method(this, 0x60, 0x298);
    platform::call1(update, p32(this));

    // (*(this + 0x5D4) != 0) && (*(this + 0x5CC) - 1U < 2)
    if platform::read_u32(this + 0x5D4) != 0
        && platform::read_u32(this + 0x5CC).wrapping_sub(1) < 2
    {
        let notify = vtable_method(this, 0x60, 0xD4);
        platform::call2(notify, p32(this), p32(DAT_80353010_B));
    }
}

