// ---------------------------------------------------------------------------
// Host-side ABI wrappers for this lane
// ---------------------------------------------------------------------------

/// An 8-byte-aligned 0x30-byte matrix scratch block.
#[repr(C, align(8))]
struct W205fMatrix48([u8; 0x30]);

/// An 8-byte-aligned 0x34-byte matrix scratch block (the `0x80168180` /
/// `0x8016F130` block needs the trailing word the C export reserves).
#[repr(C, align(8))]
struct W205fMatrix52([u8; 0x34]);

/// Calls `void(f32, u32, u32)`; the float goes in `f1`, the words in
/// `r3`/`r4`.
///
/// # Safety
/// `addr` must be the entry point of a routine with this ABI.
#[inline]
unsafe fn w205f_call_f32_u32x2(addr: usize, a: f32, b: u32, c: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f32, u32, u32));
    f(a, b, c)
}

/// Calls `void(f64, u32, u32)`; the double goes in `f1`, the words in
/// `r3`/`r4`.
///
/// # Safety
/// `addr` must be the entry point of a routine with this ABI.
#[inline]
unsafe fn w205f_call_f64_u32x2(addr: usize, a: f64, b: u32, c: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32, u32));
    f(a, b, c)
}

/// Calls `void(f64, f64, f64, u32)`; the doubles go in `f1..f3`, the pointer
/// in `r3`.
///
/// # Safety
/// `addr` must be the entry point of a routine with this ABI and `out` must
/// address at least 0x30 writable bytes.
#[inline]
unsafe fn w205f_call_f64x3_u32(addr: usize, a: f64, b: f64, c: f64, out: u32) {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, f64, u32));
    f(a, b, c, out)
}

/// Calls `void(f64, f64, u32, u32, u32, u32)`; the doubles go in `f1`/`f2`,
/// the words in `r3..r6`.
///
/// # Safety
/// `addr` must be the entry point of a routine with this ABI.
#[inline]
unsafe fn w205f_call_f64x2_u32x4(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32, f: u32) {
    let g = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32, u32, u32));
    g(a, b, c, d, e, f)
}

