const FN_80064D10_B: usize = 0x8006_4D10;

/// `0x80020BF0(this, child)`: controller-side button gate; installed in the
/// `+0x6D0` slot of the [`fn_80036d40`] record.
const FN_80020BF0_B: usize = 0x8002_0BF0;

/// `0x80020E70(this, child)`: second wrapper of the same button gate;
/// installed in the `+0x6D4` slot.
const FN_80020E70_B: usize = 0x8002_0E70;

/// `0x800210F0`: `b 0x80021010`, a real child-update body; installed in the
/// `+0x6D8` slot.
const FN_800210F0_B: usize = 0x8002_10F0;

/// `r13 - 0x56B8` (`0x80429FC8`): global handle passed as the manager to
/// `0x800D0470`.
const G_SDA_56B8_B: usize = SDA_BASE - 0x56B8;

/// `r13 - 0x5680` (`0x8042A000`): global handle passed as the manager to
/// `0x800D87B0`.
const G_SDA_5680_B: usize = SDA_BASE - 0x5680;

/// `SDA2_BASE - 0x7AF8` (`0x8042B588`): `f32 8.0`.
const F32_SDA2_7AF8_B: usize = SDA2_BASE - 0x7AF8; // 8.0

/// `SDA2_BASE - 0x7AF4` (`0x8042B58C`): `f32 1.0`.
const F32_SDA2_7AF4_B: usize = SDA2_BASE - 0x7AF4; // 1.0

/// `SDA2_BASE - 0x7AF0` (`0x8042B590`): `f32 -8.0`.
const F32_SDA2_7AF0_B: usize = SDA2_BASE - 0x7AF0; // -8.0

/// `SDA2_BASE - 0x7AEC` (`0x8042B594`): `f32 16.0`.
const F32_SDA2_7AEC_B: usize = SDA2_BASE - 0x7AEC; // 16.0

/// `SDA2_BASE - 0x7AE8` (`0x8042B598`): `f32 0.0`.
const F32_SDA2_7AE8_B: usize = SDA2_BASE - 0x7AE8; // 0.0

