/// Builds one `daEnObjCoinBlock_c` state descriptor and links it into the
/// state registry.
///
/// observed copy order (identical in all seven blocks): the nine words of the
/// `0x24`-byte parameter record are loaded first, then `0x8015F7C0` names the
/// descriptor, then the vtable and the nine fields are stored, then
/// `0x802DC780` registers the descriptor with its event object `desc - 0x10`.
///
/// # Confidence
/// high - see [`fn_80037750`]; every load, store and call is literal.
unsafe fn w207c_build_state(desc: usize, params: usize, name: usize) {
    // observed: the original stages all nine words on the stack before the
    // name call (`lwz r27,0x0(r29)` .. `lwz r0,0x8(r5)`).
    let p0 = platform::read_u32(params);
    let p1 = platform::read_u32(params + 0x04);
    let p2 = platform::read_u32(params + 0x08);
    let p3 = platform::read_u32(params + 0x0C);
    let p4 = platform::read_u32(params + 0x10);
    let p5 = platform::read_u32(params + 0x14);
    let p6 = platform::read_u32(params + 0x18);
    let p7 = platform::read_u32(params + 0x1C);
    let p8 = platform::read_u32(params + 0x20);

    platform::call2(FN_8015F7C0, p32(desc), p32(name));
    platform::write_u32(desc, VT_COINBLOCK_STATE_C);
    platform::write_u32(desc + 0x0C, p6);
    platform::write_u32(desc + 0x10, p7);
    platform::write_u32(desc + 0x14, p8);
    platform::write_u32(desc + 0x18, p3);
    platform::write_u32(desc + 0x1C, p4);
    platform::write_u32(desc + 0x20, p5);
    platform::write_u32(desc + 0x24, p0);
    platform::write_u32(desc + 0x28, p1);
    platform::write_u32(desc + 0x2C, p2);
    platform::call3(
        FN_802DC780,
        p32(desc),
        p32(FN_80037D20_C),
        p32(desc - 0x10),
    );
}

