    platform::write_u32(this + 0x178, platform::read_u32(this + 0x178) & 0xFFFF_FF4F);
    platform::write_u32(this + 0x7CC, 0);
    platform::write_u8(this + 0x175, 0);
    write_f32(this + 0x11C, read_f32(F32_SDA2_7AD0_F));
    write_f32(this + 0xF4, read_f32(F32_SDA2_7AD0_F));
    write_f32(this + 0xF8, read_f32(F32_SDA2_7A20_A));
    write_f32(this + 0xFC, read_f32(F32_SDA2_7AD0_F));

    platform::write_u32(this + 0x614, platform::read_u32(this + 0x614) & 0xFB64_FBFF);
    platform::write_u32(this + 0x620, platform::read_u32(this + 0x620) & 0xFFF3_FFFF);
    platform::write_u32(this + 0x630, platform::read_u32(this + 0x630) & 0xFF64_FBFF);
    platform::write_u32(this + 0x640, platform::read_u32(this + 0x640) & 0xFFF3_FFFF);

