const F32_SDA2_79C0_E: usize = SDA2_BASE - 0x79C0;

/// `r2 - 0x79D0` = `0x8042B6B0`: two-`f32` side table `{0.5, -0.5}` indexed by
/// the `+0x348` side byte, giving the signed advance speed.
const TABLE_F32_79D0_E: usize = SDA2_BASE - 0x79D0;

/// `r2 - 0x79C4` = `0x8042B6BC`: two-`s16` side-angle table
/// `{12000, -12000}` indexed by the `+0x348` side byte and stored to `+0x102`.
///
/// observed: ELF bytes are `2E E0 D1 20` (`12000`, `-12000`).
const TABLE_S16_79C4_E: usize = SDA2_BASE - 0x79C4;

/// `r2 - 0x79AC` = `0x8042B6D4`: `f32 1.0`, the second `0x80169F80` /
