/// Static factory for the spin state: fetches the actor record, resets its
/// movement fields, posts sound `0x1BB` and installs the six-word contact
/// descriptor around it.
///
/// # Original
/// - Ghidra: `FUN_8003f6b0` at `0x8003F6B0` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8003f6b0_FUN_8003f6b0.c`
/// - Removed: the modelled `0x802DCD74`/`0x802DCDC0` calls. They are the
///   `_savegpr_27`/`_restgpr_27` compiler helpers (register spill/restore
///   only); the actor record is the incoming `r3`.
/// - observed: prologue `stwu r1,-0x30(r1)`, terminal `bclr` at
///   `0x8003F7A8`; `252` (`0xFC`) is the exact code extent.
///
/// # Arguments
/// - `param_1`: actor record (`r3`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x7C4`, `+0xEC`, `+0x100`, `+0x884`, `+0xF4`, `+0x118`, `+0x77C`,
/// `+0x614..+0x63C`, `+0x168` and `+0x16C`, posts sound `0x1BB` through the
/// `r13 - 0x5924` manager and installs the contact descriptor.
///
/// # Safety
/// `param_1` must be a live, initialised actor record.
///
/// # Confidence
/// medium - all eleven descriptor words are literal (the `0xFFFFC000` one is
/// the signed `-0x4000` the export prints); the field meanings are only named
/// by position.
pub unsafe fn fn_8003f6b0(param_1: usize) {
    let obj = param_1;

    platform::write_u8(obj + 0x7C4, 0);
    write_f32(obj + 0xEC, read_f32(F32_SDA2_7964_E));
    platform::write_u16(obj + 0x100, 0x8000);
    platform::write_u32(obj + 0x884, 0x8000);
    write_f32(obj + 0xF4, read_f32(F32_SDA2_79C0_E));
    write_f32(obj + 0x118, read_f32(F32_SDA2_79B0_E));
    platform::write_u32(obj + 0x77C, 1);

    let mut record = [0u32; 2];
    platform::call2(
        FN_8006A4B0,
        p32(core::ptr::addr_of_mut!(record) as usize),
        p32(obj + 0xAC),
    );
    platform::call4(
        FN_80197F00_D,
        platform::read_u32(G_SDA_5924_F),
        0x1BB,
        p32(core::ptr::addr_of!(record) as usize),
        0,
    );

    platform::write_u32(obj + 0x61C, 0x0000_C000);
    platform::write_u32(obj + 0x614, 0);
    platform::write_u32(obj + 0x618, 0);
    platform::write_u32(obj + 0x620, 1);
    platform::write_u32(obj + 0x624, 0xFFFF_C000);
    platform::write_u32(obj + 0x628, 0x0000_4000);
    platform::write_u32(obj + 0x62C, 0);
    platform::write_u32(obj + 0x630, 1);
    platform::write_u32(obj + 0x634, 0x0000_7000);
    platform::write_u32(obj + 0x638, 0x0000_5000);
    platform::write_u32(obj + 0x63C, 0x0000_8000);

    platform::call5(
        FN_8006D090,
        p32(obj + 0x1EC),
        p32(obj),
        p32(obj + 0x620),
        p32(obj + 0x614),
        p32(obj + 0x630),
    );

    write_f32(obj + 0x168, read_f32(F32_SDA2_79B4_E));
    write_f32(obj + 0x16C, read_f32(F32_SDA2_79BC_E));
}

