/// `+0x414..+0x432` block on `this`.
const FN_800A0DC0_A261: usize = 0x800A_0DC0;

/// `0x8016A340(node, -1)`: sprite/node release with a signed flag.
const FN_8016A340_A261: usize = 0x8016_A340;

/// `0x80358004`: owner-chain descriptor tested through slot `+0x14` by
/// [`fn_8003de00`], [`fn_80038670`] and [`fn_8003a010`] siblings.
const DAT_80358004_A261: usize = 0x8035_8004;

/// `0x802EE7D0`: five-operand parameter block handed to [`fn_8006d090`] by
/// [`fn_8003e940`].
const DAT_802EE7D0_A261: usize = 0x802E_E7D0;

/// `0x8009_5480`: shared per-phase scene update, the tail of
/// [`fn_80038670`].
const FN_80095480_A261: usize = 0x8009_5480;

/// `r2 - 0x79C0` = `0x8042B6C0`: `0.0f`.
const F32_SDA2_79C0_A261: usize = SDA2_BASE - 0x79C0;

/// `r2 - 0x7ABC` = `0x8042B5C4`: `1.0f`.
const F32_SDA2_7ABC_A261: usize = SDA2_BASE - 0x7ABC;

/// `r2 - 0x69AC` = `0x8042C6D4`: `0.5f`.
const F32_SDA2_69AC_A261: usize = SDA2_BASE - 0x69AC;

/// `r2 - 0x6994` = `0x8042C6EC`: `-1.0f`.
const F32_SDA2_6994_A261: usize = SDA2_BASE - 0x6994;

/// `r2 - 0x699C` = `0x8042C6E4`: `32.0f`.
