/// [`fn_8002e330`].
const D262_F32_4500_7C34: usize = SDA2_BASE - 0x7C34; // 0x8042B44C, 4500.0

/// `r2 - 0x7C4C` = `0x8042B434`: `f32 0.2815f`, the base value added to the
