/// Asks the `+0x394` owner chain whether it names `descriptor`.
///
/// Models the repeated `+0x394 -> +0x28` call, the `+0x14` name test on the
/// returned owner and the compiler's `neg/or/rlwinm` boolean normalization.
///
/// # Original
/// Host-side helper; no binary address. Models the five-instruction block that
/// opens [`fn_80038830`], [`fn_800389e0`], [`fn_80039010`], [`fn_800393a0`] and
/// [`fn_8003b200`].
///
/// # Safety
/// `this + 0x394` must hold a live owner object with a vtable slot `+0x28`.
///
/// # Confidence
/// high - the slot offsets and the normalization are literal.
unsafe fn a262_owner_names(this: usize, descriptor: usize) -> bool {
    let owner_slot = vtable_method(this, 0x394, 0x28);
    let owner = platform::call1(owner_slot, p32(this + 0x394)) as usize;
    let name_slot = vtable_method(owner, 0, 0x14);
    platform::call2(name_slot, p32(owner), p32(descriptor)) != 0
}

/// `0x80064A30(f32 x, f32 z) -> u32` with the two floats in `f1`/`f2`.
///
/// # Original
/// Host-side helper; no binary address. Models the `bl 0x80064A30` pairs in
/// [`fn_80039bf0`] and [`fn_800393a0`].
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn a262_call_2f(addr: usize, x: f32, z: f32) -> u32 {
    let call = crate::platform::guest_fn!(addr, fn(f32, f32) -> u32);
    call(x, z)
}

/// Calls `f(f32, f32, u32, u32, u32, u32)`: both floats in `f1`/`f2`, then
/// `r3..r6`.
///
/// # Original
/// Host-side helper; no binary address. Models the `+0x3FC` call of
/// [`fn_800392f0`], whose `f1` and `f2` are both live across the pointer
/// materialisation.
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// medium - the float count is inferred from the two live `f` registers; the
/// integer arguments are literal.
#[inline]
unsafe fn a262_call_2f_4u(addr: usize, x: f32, z: f32, a: u32, b: u32, c: u32, d: u32) -> u32 {
    let call = crate::platform::guest_fn!(addr, fn(f32, f32, u32, u32, u32, u32) -> u32);
    call(x, z, a, b, c, d)
}

/// The duplicated "resolve owner then pick the digit slot or the `+0x150`
/// carrier" block of [`fn_800389e0`] (`0x80038B28` and `0x80038DF0`).
///
/// # Original
/// Host-side helper; no binary address. Models the second half of
/// [`fn_800389e0`], emitted twice by the compiler.
///
/// # Safety
/// `sub + 0x2A78` must hold a resolvable owner when the call answers non-zero.
///
/// # Confidence
/// high - the two emit sites are instruction-for-instruction identical.
unsafe fn a262_owner_publish(this: usize, sub: usize) {
    let owner = platform::call1(FN_80162D00_A262, platform::read_u32(sub + 0x2A78)) as usize;
    if owner == 0 {
        return;
    }

    if platform::read_u8(owner + 0x38C) == 1 {
        let digit_slot = vtable_method(owner, 0x60, 0x6C);
        let digit = platform::call1(digit_slot, p32(owner)) as usize;
        let index = platform::read_u8(digit) as i8 as i32;
        platform::write_u16((this as isize + 0x504 + index as isize * 2) as usize, 10);
    } else {
        platform::write_u32(owner + 0x150, p32(this));
        let carrier = platform::read_u32(owner);
        platform::write_u32(this + 0x7B0, carrier);
        platform::write_u32(this + 0x7B4, 12);
    }
}

/// The duplicated "contact class burst" block of [`fn_800389e0`]
/// (`0x80038AD8` and `0x80038DA0`).
///
/// `0x8009F5F0(sub)` is clamped up to `1`, the class byte comes from the asked
/// actor's slot `+0x6C`, and `0x800E20A0` receives `(0.0, 24.0, manager, this,
/// count, class)`.
///
/// # Original
/// Host-side helper; no binary address. Models the block emitted twice inside
/// [`fn_800389e0`].
///
/// # Safety
/// `sub + 0x60` must be a vtable with slot `+0x6C`.
///
/// # Confidence
/// high - both emit sites and all five arguments are literal.
unsafe fn a262_contact_burst(this: usize, sub: usize) {
    let count_slot = vtable_method(sub, 0x60, 0xE0);
    if platform::call1(count_slot, p32(sub)) != 0 {
        return;
    }

    let mut count = platform::call1(FN_8009F5F0, p32(sub)) as i32;
    if count < 1 {
        count = 1;
    }
    let digit_slot = vtable_method(sub, 0x60, 0x6C);
    let digit = platform::call1(digit_slot, p32(sub)) as usize;
    let class = platform::read_u8(digit) as i8 as i32;
    w205d_call_2f_4u(
        B261_FN_800E20A0,
        read_f32(F32_SDA2_9C08_A262) as f64,
        read_f32(F32_SDA2_9C0C_A262) as f64,
        platform::read_u32(G_SDA_5630_F),
        p32(this),
        count as u32,
        class as u32,
    );
}

