///
/// # Confidence
/// high - four instructions plus the call are literal.
pub unsafe fn fn_8003ec40(this: usize) {
    fn_8003be00(this);

    if platform::read_u32(this + 0x77C) == 2 {
        platform::write_u16(this + 0x102, 0);
    }
}

/// Adds the per-frame walk step to the two `+0x100`/`+0x102` angle words.
///
/// Outside state `2` it forwards to [`fn_8003be80`]. In state `2` the `x` step
/// is the shipped `s16` constant at `r2 - 0x6DA4` (zero) and the `y` step is
/// the `s16` entry `0x8042B6F0[2 * (+0x459)]`; when `+0x45D` is set both steps
/// are halved with a truncating `fctiwz` of `0.5 * step`. The steps are added
/// to the sign-extended halfwords at `+0x100`/`+0x102`, then
/// [`FN_8006CDE0`] and [`FN_800955F0`] run.
///
/// # Original
/// - Ghidra: none (untabled; corpus row
///   `0x8003ec90,216,0x8003ec38,0x80306574`)
/// - Evidence: `work/wave262/a/disasm_next12.txt`
/// - observed: `blr` at `0x8003ED64`, extent exactly 216 bytes.
/// - observed: the `lha`/`xoris 0x8000`/`fctiwz` block is the signed-int to
///   float conversion idiom with the magic double at `r2 - 0x7988`; it is
///   written below as `(step as f32 * 0.5) as i32`.
///
/// # Arguments
/// - `this`: the actor; `+0x77C` state, `+0x459` table index, `+0x45D` gate,
///   `+0x100`/`+0x102` angle halfwords.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two angle writes and two tail calls.
///
/// # Safety
/// `this` must be a live actor and both tables mapped.
///
/// # Confidence
/// high - the state test, both table bases and the two stores are literal.
pub unsafe fn fn_8003ec90(this: usize) {
    if platform::read_u32(this + 0x77C) != 2 {
        fn_8003be80(this);
        return;
    }

    let mut x_step = platform::read_u16(S16_SDA2_925C_A262) as i16 as i32;
    let row = platform::read_u8(this + 0x459) as usize;
    let mut y_step =
        platform::read_u16(TABLE_S16_SDA2_7990_A262 + row * 2) as i16 as i32;

    if platform::read_u8(this + 0x45D) != 0 {
        x_step = (x_step as f32 * read_f32(F32_SDA2_9144_A262)) as i32;
        y_step = (y_step as f32 * read_f32(F32_SDA2_9144_A262)) as i32;
    }

    let x = platform::read_u16(this + 0x100) as i16 as i32;
    let y = platform::read_u16(this + 0x102) as i16 as i32;
    platform::write_u16(this + 0x100, x.wrapping_add(x_step) as u16);
    platform::write_u16(this + 0x102, y.wrapping_add(y_step) as u16);

    platform::call1(FN_8006CDE0, p32(this));
    platform::call1(FN_800955F0, p32(this));
}

/// Starts the `+0x3FC` effect on the contact and sets the `0x80429F10`
/// `+0x138` flag.
///
/// Guarded by slot `+0x2DC`. The speed argument is `0.2815f + *(f32*)(r13 -
/// 0x5370)`; the second float is the contact's `+0x10C`, zeroed when `+0x7CC`
/// is set and its magnitude is below `1.0f`. The `+0x3FC` call receives
/// `(f1, f2, other, 1, 0, 2)`, and `*(0x80429F10) + 0x138` is then set to `1`.
///
/// # Original
/// - Ghidra: none (untabled; corpus row
///   `0x800392f0,172,0x80038800,0x80305b9c`)
/// - Evidence: `work/wave262/a/disasm_next12.txt`
/// - observed: `blr` at `0x80039398`, extent exactly 172 bytes.
///
/// # Arguments
/// - `this`: the actor; `+0x60` class vtable, `+0x7CC` position gate.
/// - `other`: the contact; `+0x10C` effect value and `+0x60` vtable.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One virtual effect call and one global flag write.
///
/// # Safety
/// `this + 0x60` and `other + 0x60` must be live vtables; both globals must be
/// mapped.
///
/// # Confidence
/// medium - all operands and the two globals are literal; that the second
/// float is an argument is inferred from its liveness across the call.
pub unsafe fn fn_800392f0(this: usize, other: usize) {
    if platform::call1(vtable_method(this, 0x60, 0x2DC), p32(this)) != 0 {
        return;
    }

    let speed = read_f32(F32_SDA2_8560_A262) + read_f32(G_SDA_5370_A262);
    let mut effect = read_f32(other + 0x10C);
    if platform::read_u32(this + 0x7CC) != 0
        && effect.abs() < read_f32(F32_SDA2_8544_A262)
    {
        effect = read_f32(F32_SDA2_8530_A262);
    }

    a262_call_2f_4u(
        vtable_method(other, 0x60, 0x3FC),
        speed,
        effect,
        p32(other),
        1,
        0,
        2,
    );

    let global = platform::read_u32(G_SDA_5770_A262) as usize;
    platform::write_u32(global + 0x138, 1);
}

