/// # Arguments
/// - `this`: the scene; `+0x102` angle limit, `+0x274` motion mask, `+0x348`
///   side byte, `+0x394` owner object and the model records.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Per-frame updates, one clamped `i16` step, up to four virtual calls, up to
/// two float stores and one transform rebuild.
///
/// # Safety
/// `this + 0x102` must be a writable `i16`; the side byte must index
/// `0x8042C1A4` (`0`/`1` for the shipped paths); the model and owner records
/// must be live.
///
/// # Confidence
/// high - every call, mask, constant and branch is literal; `slw` uses the PPC
/// shift count modulo 32, reproduced with `wrapping_shl`.
pub unsafe fn fn_800345e0(this: usize) {
    platform::call1(vtable_method(this + 0x544, 0, 0x1C), p32(this + 0x544));
    platform::call1(vtable_method(this + 0x5C0, 0, 0x14), p32(this + 0x5C0));
    platform::call1(FN_8006CDE0, p32(this));
    platform::call1(FN_800955F0, p32(this));

    let side = platform::read_u8(this + 0x348) as usize;
    let _ = crate::game::task::step_short_clamped_wrap(
        (this + 0x102) as *mut i16,
        platform::read_u16(TABLE_ANGLE_LIMITS + side * 2) as i16 as i32,
        0x200,
    );

    platform::call1(vtable_method(this, 0x60, 0x2D0), p32(this));
    let flags = platform::call1(FN_80096E60_A, p32(this)) & 0xFF;

    if flags & 1 != 0 {
        write_f32(this + 0xEC, read_f32(F32_SDA2_7B74_E));
    }

    // observed: `li r3,21` / `slw r0,r3,r0` / `and. r0,r4,r0`; the mask is
    // `0x15 << side` and the branch fires when the intersection is non-zero.
    let mask = 0x15u32.wrapping_shl(side as u32);
    if platform::read_u32(this + 0x274) & mask != 0 {
        write_f32(this + 0xAC, read_f32(this + 0xB8));
        platform::call2(
            vtable_method(this, 0x60, 0xD4),
            p32(this),
            p32(DAT_8035362C_E),
        );

        let owner = this + 0x394;
        platform::call1(vtable_method(owner, 0, 0x1C), p32(owner));
    }

    let _ = call_f32_2u(
        FN_80097170_E,
        read_f32(F32_SDA2_7B68_E),
        p32(this),
        p32(this + 0xAC),
    );
}

