/// # Safety
/// `+0x504 + 2*digit` must be a writable state slot.
///
/// # Confidence
/// high - both emit sites are instruction-for-instruction identical and all
/// offsets are literal.
unsafe fn install_shell_reset_pose(this: usize) {
    write_f32(this + 0x11C, read_f32(F32_SDA2_7A00_A263));
    platform::write_u32(this + 0x7CC, 0);
    let digit = platform::read_u8(this + 0x38D);
    let state_slot = this + 0x504 + (digit as i8 as i32 as u32) as usize * 2;
    platform::write_u16(state_slot, 16);

    let side = platform::read_u8(this + 0x348);
    write_f32(
        this + 0xF4,
        read_f32(TABLE_SDA2_7AD8_A263 + side as usize * 4),
    );
}

