/// Pane release plus the heading-aligned carry tick.
///
/// Releases `+0x7FC` through slot `+0x1C`, runs the two shared ticks and
/// `0x80096F60`, forwards `+0x274` to `0x8006EF40`, runs `0x80097050` and
/// clears `+0xEC` when the controller is in contact.
///
/// The heading `+0x102` is then stepped toward `{12000, -12000}[+0x348]` by
/// `1024`, clamping at the target. A state machine on `+0x360` follows:
/// * `1` - `+0x100 += 3072`; when the old value was negative and the sum
///   reaches `0`, `+0x100` is zeroed and the state advances to `2`;
/// * `2` - when the contact settled and the heading was clamped, `+0x7C4`
///   is cleared and state `0x80353CA8` is entered.
///
/// # Original
/// - Ghidra: none (untabled; corpus row
///   `0x8003fb10,372,0x8003f8b0,0x803066ac`)
/// - Evidence: `work/wave263/a/disasm_next12.txt`
/// - observed: `blr` at `0x8003FC80`, extent exactly 372 bytes.
///
/// # Arguments
/// - `this`: the shell actor; `+0x7FC` animation owner, `+0x102`/`+0x100`
///   angles, `+0x360` state, `+0x7C4` gate, `+0x274` state bits.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One virtual release, three shared ticks, the heading writes and (in state
/// `2`) one virtual state switch.
///
/// # Safety
/// `this + 0x7FC` and `this + 0x60` must expose their slots; the controller at
/// `+0x1EC` must be live.
///
/// # Confidence
/// high - both comparisons, the `1024`/`3072` steps, the two state values and
/// the descriptor address are literal.
pub unsafe fn fn_8003fb10(this: usize) {
    let release = vtable_method(this + 0x7FC, 0, 0x1C);
    platform::call1(release, p32(this + 0x7FC));

    platform::call1(FN_8006CDE0, p32(this));
    platform::call1(FN_800955F0, p32(this));
    platform::call1(FN_80096F60_A263, p32(this));
    platform::call2(FN_8006EF40, p32(this + 0x1EC), platform::read_u32(this + 0x274));
    platform::call1(FN_80097050_A263, p32(this));

    let mut settled = false;
    if platform::call1(FN_80070CB0_D, p32(this + 0x1EC)) != 0 {
        write_f32(this + 0xEC, read_f32(F32_SDA2_7AD0_F));
        settled = true;
    }

    let side = platform::read_u8(this + 0x348);
    let target = platform::read_u16(TABLE_S16_SDA2_79C4_A263 + side as usize * 2) as i16;
    let angle = platform::read_u16(this + 0x102) as i16;
    let mut aligned = false;
    if angle > target {
        let candidate = angle.wrapping_sub(1024);
        platform::write_u16(this + 0x102, candidate as u16);
        if candidate <= target {
            platform::write_u16(this + 0x102, target as u16);
            aligned = true;
        }
    } else if angle == target {
        aligned = true;
    } else {
        let candidate = angle.wrapping_add(1024);
        platform::write_u16(this + 0x102, candidate as u16);
        if candidate >= target {
            platform::write_u16(this + 0x102, target as u16);
            aligned = true;
        }
    }

    match platform::read_u32(this + 0x360) {
        1 => {
            let angle = platform::read_u16(this + 0x100) as i16;
            let next = angle.wrapping_add(3072);
            platform::write_u16(this + 0x100, next as u16);
            if angle < 0 && next >= 0 {
                platform::write_u16(this + 0x100, 0);
                platform::write_u32(this + 0x360, 2);
            }
        }
        2 => {
            if settled && aligned {
                platform::write_u8(this + 0x7C4, 0);
                let state = vtable_method(this, 0x60, 0xD4);
                platform::call2(state, p32(this), p32(DAT_80353CA8_A263));
            }
        }
        _ => {}
    }
}

