/// # Confidence
/// high - both descriptor addresses, the slot offsets and the branch sense are
/// literal.
pub unsafe fn fn_8003fc90(this: usize) {
    let owner_slot = vtable_method(this, 0x394, 0x28);
    let owner = platform::call1(owner_slot, p32(this + 0x394)) as usize;
    let named = platform::call2(vtable_method(owner, 0, 0x14), p32(owner), p32(DAT_80353CA8_A263));
    if named != 0 {
        let state = vtable_method(this, 0x60, 0xD4);
        platform::call2(state, p32(this), p32(DAT_80353DA8_A263));
    }
}

