/// literal; the direction roles of the side byte follow the `_D265` gate.
pub unsafe fn fn_80031730(this: usize, contact: usize) -> u32 {
    let side = platform::read_u8(this + 0x348);
    let value = read_f32(contact + 0x5C);

    let dispatch = if side == 1 {
        value > 0.0
    } else if side == 0 {
        value < 0.0
    } else {
        false
    };

    if dispatch {
        platform::call1(vtable_method(this, 0x60, 0x2CC), p32(this))
    } else {
        this as u32
    }
}

