    record[4] = read_f32(F32_SDA2_7BD4_A268).to_bits();
    record[5] = read_f32(F32_SDA2_7BD0_A268).to_bits();
    record[6] = read_f32(F32_SDA2_7BCC_A268).to_bits();

    let result = platform::call3(
        FN_800B8700_D,
        p32(this + 0x484),
        p32(record.as_mut_ptr() as usize),
        1,
    );
