    set_position(
        (read_f32(F32_0P2815_7B20_F269) + read_f32(F32_G_STAGE_8042A310_F269))
            * read_f32(F32_0P8125_7B24_F269),
        read_f32(actor + 0x10C),
        actor as u32,
        1,
        0,
        2,
    );

