// `no_std`; no allocation and no new global state.

/// `SDA2_BASE - 0x7E24` (`0x8042B25C`): `f32 -2500.0`, the start value of the
/// scene timer at `+0xB4`.
///
/// observed: the same body loads it into `+0xB4` and then adds the live scene
/// count to it, so the field holds `count - 2500.0` after a successful
/// registration.
const F32_SDA2_7E24: usize = SDA2_BASE - 0x7E24;

/// `0x8008C380`: release the animation holder at `(member)`.
const D277_FN_8008C380: usize = 0x8008_C380;
/// `0x801676A0`: release the first animation bind `(member, -1)`.
const D277_FN_801676A0: usize = 0x8016_76A0;
/// `0x80166A70`: release the second animation record `(member, -1)`.
const D277_FN_80166A70: usize = 0x8016_6A70;
/// `0x80064F50`: finish the sprite-record update `(actor, 0)`.
const D277_FN_80064F50: usize = 0x8006_4F50;

/// Registers the scene in its three-record registry and builds its model.
///
/// Steps, in original order:
///
/// 1. bits `28..29` of the `+0x04` flags select one record of
///    [`TABLE_SCENE_REGISTRY`] (stride `0x3C`); the index is published at
///    `+0x5E4`;
/// 2. [`fn_8001f6c0`] inserts `this` into that record's twelve-slot table; a
///    full table calls `0x80162510(this)` and answers `0`;
/// 3. [`fn_8001fa70`] builds the `daikonbou` model, the three scale fields
///    `+0xDC..+0xE4` are set to `1.0f`, `+0xB4` is set to `-2500.0f` and then
///    replaced by `(f32)liveCount + (-2500.0f)`;
/// 4. the two speed bytes of the flags word are copied to `+0x5F0`/`+0x5F4`,
///    the two member addresses to `+0x6C4`/`+0x6C8`, and
///    [`fn_8001ff90`]/[`fn_80020020`] refresh the descriptor and the segment
///    cursors;
/// 5. vtable slots `+0x284`, `+0x294` and `+0x28C` are called in that order,
///    and the two state bytes `+0x1E7`/`+0x6A7` are set to `3`.
///
/// The `+0x04` word is re-read into `r5` after the model build
/// (`0x8001F994`); both byte extracts come from that second copy, which is why
/// the `+0x5F0`/`+0x5F4` stores happen after the model build.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row or export for `0x8001F900`.
/// - Extent: `0x8001F900..0x8001FA40` (320 bytes); a `blr` leaf starts at
///   `0x8001FA40`, so there is no padding.
/// - Table: slot 0 of `0x80301C00` (word `0x80301C00`, offset `+0x000`).
/// - observed: `rlwinm r0,r0,4,30,31` over `lwz r0,4(r3)`; `mulli r0,r0,60`;
///   `lis r5,0x8035` / `addi r5,r5,0x2974`; the `0x43300000` integer-to-float
///   pair at `0x8001F974..0x8001F9A4` subtracts the double
///   `0x4330000080000000` at `sda2(-0x7E20)`; `lfs` reads `sda2(-0x7E28)`
///   (`1.0f`) and `sda2(-0x7E24)` (`-2500.0f`).
///
/// # Arguments
/// - `this`: scene record with the vtable pointer at `+0x60` and the flags at
///   `+0x04`.
///
/// # Returns
/// `1` when the scene was registered, `0` when the registry table is full or
/// unusable.
///
/// # Side effects
/// Writes the registry slot, `+0x5E4`, `+0x5F0..+0x5F4`, `+0x5E8..+0x5EC`,
/// `+0x6C4`, `+0x6C8`, `+0x1E7`, `+0x6A7`, `+0xB4`, `+0xDC..+0xE4`; three
/// virtual calls and the callees of steps 2-4.
///
/// # Safety
/// `this` must be a live scene with a readable vtable at `+0x60` and a valid
/// descriptor index; the three registry records must be writable.
///
/// # Confidence
/// high - every load, store, immediate and call target is literal; the
/// integer-to-float conversion is the standard MWCC `0x4330_0000` idiom.
pub unsafe fn fn_8001f900(this: usize) -> u32 {
    let flags = platform::read_u32(this + 4);
    let index = (flags >> 28) & 3;
    platform::write_u32(this + 0x5E4, index);
    let record = TABLE_SCENE_REGISTRY + index as usize * 0x3C;
    if fn_8001f6c0(record, p32(this)) == 0 {
        platform::call1(FN_80162510, p32(this));
        return 0;
    }

    fn_8001fa70(this);
    let one = read_f32(F32_SDA2_7E28);
    write_f32(this + 0xDC, one);
    write_f32(this + 0xE0, one);
    write_f32(this + 0xE4, one);
    let start = read_f32(F32_SDA2_7E24);
    write_f32(this + 0xB4, start);

    let count = fn_80020000();
    write_f32(this + 0x5E8, read_f32(this + 0xAC));
    write_f32(this + 0x5EC, read_f32(this + 0xB0));
    write_f32(this + 0xB4, count as f32 + start);

    // observed: the image re-reads `lwz r5,0x4(r31)` at `0x8001F994` after
    // `fn_8001fa70` and uses that copy for these two stores.
    let flags = platform::read_u32(this + 4);
    platform::write_u32(this + 0x5F0, flags & 0xFF);
    platform::write_u32(this + 0x5F4, (flags >> 8) & 0xFF);
    platform::write_u32(this + 0x6C4, p32(this + 0x148));
    platform::write_u32(this + 0x6C8, p32(this + 0x608));

    fn_8001ff90(this);
    fn_80020020(this);
    platform::call1(vtable_method(this, 0x60, 0x284), p32(this));
    platform::call1(vtable_method(this, 0x60, 0x294), p32(this));
    platform::call1(vtable_method(this, 0x60, 0x28C), p32(this));

    platform::write_u8(this + 0x1E7, 3);
    platform::write_u8(this + 0x6A7, 3);
    1
}

/// Releases both animation holders and removes the scene from the registry.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row or export for `0x8001FCE0`.
/// - Extent: `0x8001FCE0..0x8001FD38` (88 bytes); two zero words follow the
///   `blr`, then `0x8001FD40` starts.
/// - Table: slot 3 of `0x80301C00` (word `0x80301C0C`, offset `+0x00C`).
/// - observed: `addi r3,r3,0x148` / `bl 0x8008C380`, the same pair with
///   `+0x608`, then `lwz r0,0x5E4(r3)`, `mulli r0,r0,60`,
///   `lis 0x8035`+`addi 0x2974`, `bl 0x8001F740` and `li r3,1`.
///
/// # Arguments
/// - `this`: registered scene record.
///
/// # Returns
/// `1`, always.
///
/// # Side effects
/// Two holder releases, one registry removal, `+0x04` count decrement.
///
/// # Safety
/// `this + 0x148`, `this + 0x608` and the selected registry record must be
/// live; `+0x5E4` must hold the index written by [`fn_8001f900`].
///
/// # Confidence
/// high - the two holder addresses, the `0x3C` stride and the removal call are
/// literal.
pub unsafe fn fn_8001fce0(this: usize) -> u32 {
    platform::call1(D277_FN_8008C380, p32(this + 0x148));
    platform::call1(D277_FN_8008C380, p32(this + 0x608));
    let index = platform::read_u32(this + 0x5E4) as usize;
    fn_8001f740(TABLE_SCENE_REGISTRY + index * 0x3C, p32(this));
    1
}

