/// Runs the selected state record and closes the layout of a built wipe scene.
///
/// # Original
/// Host-side helper; no binary address. Models the identical 31-instruction body
/// of [`fn_8001bd70`], [`fn_8001c340`] and [`fn_8001c860`], whose only
/// difference is the state-table base passed as `table`.
///
/// # Safety
/// `this` must be a wipe scene; `table` must address three 12-byte records whose
/// third word is a callable function pointer.
///
/// # Confidence
/// high - guard, descriptor dispatch, layout reset and one virtual call are
/// literal.
unsafe fn d285_run_state(this: usize, table: usize) -> u32 {
    if platform::read_u8(this + 0x1B8) != 0 && platform::read_u32(this + 0x1B4) != 3 {
        // observed: `mulli r0,r0,12` / `add r12,r4,r0` / `bl 0x802DCBFC` with
        // r3 = this and r4 = the class state table.
        let _ = interface_call2::<u32>(
            table,
            p32(this),
            platform::read_u32(this + 0x1B4).wrapping_mul(12),
            p32(table),
        );
        platform::call1(FN_800C9560, p32(this + 0x14));
        let close = vtable_method(this, 0x1C, 0x10);
        platform::call1(close, p32(this + 0x14));
    }
    1
}

